import 'package:flutter_test/flutter_test.dart';
import 'package:auren/features/notification_digest/domain/notification_digest_planner.dart';
void main(){const p=NotificationDigestPlanner();final now=DateTime.utc(2026,10,12);test('separates urgent notifications and deduplicates',(){final r=p.plan([NotificationCandidate(id:'a',title:'A',urgency:NotificationUrgency.high,createdAt:now),NotificationCandidate(id:'a',title:'dup',urgency:NotificationUrgency.low,createdAt:now),NotificationCandidate(id:'b',title:'B',urgency:NotificationUrgency.low,createdAt:now)],now:now);expect(r.immediate.map((e)=>e.id),['a']);expect(r.digest.map((e)=>e.id),['b']);});test('filters read, future and old candidates',(){final r=p.plan([NotificationCandidate(id:'r',title:'R',urgency:NotificationUrgency.low,createdAt:now,read:true),NotificationCandidate(id:'f',title:'F',urgency:NotificationUrgency.high,createdAt:now.add(const Duration(days:1))),NotificationCandidate(id:'o',title:'O',urgency:NotificationUrgency.low,createdAt:now.subtract(const Duration(days:8)))],now:now);expect(r.immediate,isEmpty);expect(r.digest,isEmpty);});}
